package cl.duoc.tienda.notificacion.controller;
import cl.duoc.tienda.notificacion.dto.*; import cl.duoc.tienda.notificacion.model.*; import cl.duoc.tienda.notificacion.service.*; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import java.net.URI; import java.util.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/notificaciones") @Tag(name="Notificacion",description="CRUD de notificaciones") public class NotificacionController { private final NotificacionService service; public NotificacionController(NotificacionService s){service=s;} @GetMapping @Operation(summary="Listar notificaciones") public ResponseEntity<List<Notificacion>> listar(){return ResponseEntity.ok(service.listar());} @GetMapping("/{id}") public ResponseEntity<Notificacion> buscar(@PathVariable Long id){return ResponseEntity.ok(service.buscar(id));} @PostMapping public ResponseEntity<Notificacion> crear(@Valid @RequestBody NotificacionRequest d){Notificacion e=service.guardar(d);return ResponseEntity.created(URI.create("/notificaciones/"+e.getId())).body(e);} @PutMapping("/{id}") public ResponseEntity<Notificacion> actualizar(@PathVariable Long id,@Valid @RequestBody NotificacionRequest d){return ResponseEntity.ok(service.actualizar(id,d));} @DeleteMapping("/{id}") public ResponseEntity<Void> eliminar(@PathVariable Long id){service.eliminar(id);return ResponseEntity.noContent().build();} }
